void cRPath::initialize_looptheloopw_path_template_pair(
    float curve_source, int width_cells_, bool side_exit,
    char* texture_a, char* texture_b, char* cap_texture)
{
    AttachmentSample*& live_primary_samples = primary_samples;
    AttachmentSample*& live_secondary_samples = secondary_samples;
    int curve_count;
    int i;
    float sample_f;

    kind = PATH_TEMPLATE_KIND_LOOPTHELOOP_FAMILY;
    float loop_wiggle = 0.0f;
    if (width_cells_ == 4) {
        kind = PATH_TEMPLATE_KIND_LOOPTHELOOPW;
        loop_wiggle = 0.30000001f;
    }
    is_mirrored_x = 0;
    side_exit_mode = 0;
    width_cells = width_cells_;
    curve_count = (int)(curve_source * 6.2831855f);
    width_or_scale = 1.0f;
    int loop_segment_count = curve_count + 14;
    segment_count = loop_segment_count;
    segment_count_f = (float)loop_segment_count;
    float curve_count_f = (float)curve_count;
    float loop_radius = curve_count_f * 0.15915494f;
    GetNodes();
    has_entry_mesh_transition = 1;

    for (i = 0; i < 7; ++i) {
        sample_f = (float)i;
        live_primary_samples[i].center_x = (float)width_cells * 0.5f - 4.0f
            - loop_wiggle * (sample_f / 7.0f);
        live_primary_samples[i].rotation_scalar_98 = 0.0f;
        live_primary_samples[i].rotation_scalar_94 = 0.0f;
        live_primary_samples[i].special_scalar = 0.0f;
        live_primary_samples[i].lateral_scale = 1.0f;
        live_primary_samples[i].transform.Identity();
        live_primary_samples[i].transform.position.x = live_primary_samples[i].center_x;
        live_primary_samples[i].transform.position.y = 0.0f;
        live_primary_samples[i].transform.position.z = sample_f;
        live_primary_samples[i].delta_length = 1.0f;

        live_secondary_samples[i].transform.Identity();
        live_secondary_samples[i].transform.position.x = live_primary_samples[i].center_x;
        live_secondary_samples[i].transform.position.y = 0.49000001f;
        live_secondary_samples[i].transform.position.z = sample_f;
        live_secondary_samples[i].delta_length = 1.0f;
    }

    for (i = 0; i < 7; ++i) {
        int sample_index = curve_count + 7 + i;
        live_primary_samples[sample_index].center_x =
            (1.0f - (float)i * 0.16666667f) * loop_wiggle
            + (4.0f - (float)width_cells * 0.5f);
        live_primary_samples[sample_index].rotation_scalar_98 = 0.0f;
        live_primary_samples[sample_index].rotation_scalar_94 = 0.0f;
        live_primary_samples[sample_index].special_scalar = 0.0f;
        live_primary_samples[sample_index].lateral_scale = 1.0f;
        live_primary_samples[sample_index].transform.Identity();
        live_primary_samples[sample_index].transform.position.x =
            live_primary_samples[sample_index].center_x;
        live_primary_samples[sample_index].transform.position.y = 0.0f;
        live_primary_samples[sample_index].transform.position.z = (float)(i + 7);
        live_primary_samples[sample_index].delta_length = 1.0f;

        live_secondary_samples[sample_index].transform.Identity();
        live_secondary_samples[sample_index].transform.position.x =
            live_primary_samples[sample_index].center_x;
        live_secondary_samples[sample_index].transform.position.y = 0.49000001f;
        live_secondary_samples[sample_index].transform.position.z = (float)(i + 7);
        live_secondary_samples[sample_index].delta_length = 1.0f;
    }

    i = 0;
    if (curve_count > 0) {
        float secondary_radius = loop_radius - 0.49000001f;
        do {
            int sample_index = i + 7;
            sample_f = (float)i;
            float angle = sample_f * 6.2831855f / curve_count_f;
            float roll = Sin(angle * 0.5f) * Sin(angle * 8.0f) * 0.39269909f;
            live_primary_samples[sample_index].center_x =
                (live_primary_samples[loop_segment_count - 1].center_x
                    - live_primary_samples[0].center_x)
                * sample_f / curve_count_f + live_primary_samples[0].center_x;
            live_primary_samples[sample_index].center_x +=
                Sin(angle * 0.5f + 4.712389f) * loop_wiggle;
            live_primary_samples[sample_index].rotation_scalar_98 = 0.0f;
            live_primary_samples[sample_index].rotation_scalar_94 = 0.0f;
            live_primary_samples[sample_index].special_scalar = 0.0f;
            live_primary_samples[sample_index].lateral_scale = 1.0f;
            live_primary_samples[sample_index].transform.Identity();
            live_primary_samples[sample_index].transform.position.x =
                live_primary_samples[sample_index].center_x;
            live_primary_samples[sample_index].transform.position.z =
                Sin(angle) * loop_radius + 7.0f;
            live_primary_samples[sample_index].transform.position.y =
                loop_radius - Cos(angle) * loop_radius;

            live_secondary_samples[sample_index].transform.Identity();
            live_secondary_samples[sample_index].transform.position.x =
                live_primary_samples[sample_index].center_x;
            live_secondary_samples[sample_index].transform.position.z =
                Sin(angle) * secondary_radius + 7.0f;
            live_secondary_samples[sample_index].transform.position.y =
                loop_radius - Cos(angle) * secondary_radius;

            live_primary_samples[sample_index].transform.basis_right =
                Vector3(1.0f, 0.0f, 0.0f);
            live_primary_samples[sample_index].transform.basis_up.x = 0.0f;
            live_primary_samples[sample_index].transform.basis_up.y =
                loop_radius - live_primary_samples[sample_index].transform.position.y;
            live_primary_samples[sample_index].transform.basis_up.z =
                7.0f - live_primary_samples[sample_index].transform.position.z;
            live_primary_samples[sample_index].transform.basis_up.Normalize();
            live_primary_samples[sample_index].transform.basis_forward.Cross(
                live_primary_samples[sample_index].transform.basis_right,
                live_primary_samples[sample_index].transform.basis_up);
            live_primary_samples[sample_index].transform.RotLocalZ(roll);

            live_secondary_samples[sample_index].transform.basis_right =
                Vector3(1.0f, 0.0f, 0.0f);
            live_secondary_samples[sample_index].transform.basis_up.x = 0.0f;
            live_secondary_samples[sample_index].transform.basis_up.y =
                loop_radius - live_secondary_samples[sample_index].transform.position.y;
            live_secondary_samples[sample_index].transform.basis_up.z =
                7.0f - live_secondary_samples[sample_index].transform.position.z;
            live_secondary_samples[sample_index].transform.basis_up.Normalize();
            live_secondary_samples[sample_index].transform.basis_forward.Cross(
                live_secondary_samples[sample_index].transform.basis_right,
                live_secondary_samples[sample_index].transform.basis_up);

            live_secondary_samples[sample_index].transform.RotLocalZ(roll);
            ++i;
        } while (i < curve_count);
    }

    i = 0;
    if (segment_count - 1 > 0) {
        do {
            live_primary_samples[i].delta_dir_to_next =
                live_primary_samples[i + 1].transform.position -
                live_primary_samples[i].transform.position;
            live_primary_samples[i].delta_length =
                live_primary_samples[i].delta_dir_to_next.Normalize();

            live_secondary_samples[i].delta_dir_to_next =
                live_secondary_samples[i + 1].transform.position -
                live_secondary_samples[i].transform.position;
            live_secondary_samples[i].delta_length =
                live_secondary_samples[i].delta_dir_to_next.Normalize();
            ++i;
        } while (i < segment_count - 1);
    }

    live_primary_samples[segment_count - 1].delta_dir_to_next = Vector3(0.0f, 0.0f, 1.0f);
    live_primary_samples[segment_count - 1].delta_length = 1.0f;
    live_secondary_samples[segment_count - 1].delta_dir_to_next = Vector3(0.0f, 0.0f, 1.0f);
    live_secondary_samples[segment_count - 1].delta_length = 1.0f;

    build_strip_mesh(width_cells, segment_count, strip_mesh, live_primary_samples, texture_a, texture_b);

}

