            sample_offset += (int)sizeof(PathAttachmentSample);
        } while (i < curve_count);
    }

    compute_terminal_deltas(this);

    build_strip_mesh(this, texture_a, texture_b);

    CalcLengthZ();
    (void)side_exit;
    (void)cap_texture;
}
